**工具名称：WebFingerprint**

**核心功能：**

1.  **操作系统识别：** 基于 HTTP 头部信息、TCP 属性、默认页面等。
2.  **中间件版本识别：** 基于 HTTP 头部信息、错误页面、特定 URL 路径等。
3.  **WAF 类型识别：** 基于 HTTP 头部信息、响应行为、特定 URL 路径等。

**技术栈：**

*   **Python：** 主要编程语言。
*   **Requests：** 用于发送 HTTP 请求。
*   **BeautifulSoup4：** 用于解析 HTML 响应。
*   **re：** 用于正则表达式匹配。
*   **socket：** 用于获取 TCP 属性。
*   **Nmap (可选):** 用于更全面的 TCP 属性扫描。

**代码框架：**

```python
import requests
import re
import socket
import nmap  # 可选，需要安装 nmap
from bs4 import BeautifulSoup

class WebFingerprint:
    def __init__(self, target_url):
        self.target_url = target_url
        self.headers = {'User-Agent': 'WebFingerprint/1.0'}  # 设置 User-Agent

    def get_os(self):
        """尝试识别操作系统"""
        try:
            response = requests.get(self.target_url, headers=self.headers, timeout=5)
            server_header = response.headers.get('Server')

            if server_header:
                if 'Windows' in server_header:
                    return 'Windows'
                elif 'Linux' in server_header:
                    return 'Linux'
                else:
                    return 'Unknown (Server Header: {})'.format(server_header)
            else:
                return 'Unknown'
        except requests.exceptions.RequestException as e:
            print(f"Error getting OS: {e}")
            return 'Unknown'

    def get_middleware(self):
        """尝试识别中间件和版本"""
        middleware = {}
        try:
            response = requests.get(self.target_url, headers=self.headers, timeout=5)
            content = response.text

            # 尝试识别 Apache
            apache_match = re.search(r'Server: Apache\/([0-9\.]+)', content)
            if apache_match:
                middleware['Apache'] = apache_match.group(1)

            # 尝试识别 Nginx
            nginx_match = re.search(r'Server: nginx\/([0-9\.]+)', content)
            if nginx_match:
                middleware['Nginx'] = nginx_match.group(1)

            # 尝试识别 IIS
            iis_match = re.search(r'Server: Microsoft-IIS\/([0-9\.]+)', content)
            if iis_match:
                middleware['IIS'] = iis_match.group(1)
        except requests.exceptions.RequestException as e:
            print(f"Error getting middleware: {e}")
        return middleware

    def get_waf(self):
        """尝试识别 WAF 类型"""
        waf_types = {
            'ModSecurity': re.compile(r'ModSecurity'),
            'Cloudflare': re.compile(r'Cloudflare'),
            'Akamai': re.compile(r'Akamai'),
            'AWS WAF': re.compile(r'AWS WAF'),
            # 添加更多 WAF 类型
        }

        try:
            response = requests.get(self.target_url, headers=self.headers, timeout=5)
            content = response.text

            for waf_type, pattern in waf_types.items():
                if pattern.search(content):
                    return waf_type
        except requests.exceptions.RequestException as e:
            print(f"Error getting WAF: {e}")
        return 'Unknown'

    def get_tcp_attributes(self):
        """获取 TCP 属性 (可选，需要 nmap)"""
        try:
            nm = nmap.PortScanner()
            nm.scan(self.target_url, arguments='-T4')  # 调整扫描速度
            tcp_attributes = nm[self.target_url]['tcp']
            return tcp_attributes
        except Exception as e:
            print(f"Error getting TCP attributes: {e}")

