using System;
using System.Reflection;
using System.Runtime.InteropServices;

public class ReflectiveLoader
{
    [DllImport("kernel32.dll")]
    private static extern IntPtr LoadLibrary(string lpLibFileName);

    [DllImport("kernel32.dll")]
    private static extern IntPtr GetProcAddress(IntPtr hModule, string lpProcName);

    [DllImport("kernel32.dll")]
    private static extern void FreeLibrary(IntPtr hModule);

    public static IntPtr LoadAndExecute(byte[] dllBytes, string entryPointName = "DllMain")
    {
        // 1. 创建内存中的 DLL
        IntPtr dllBaseAddress = VirtualAlloc(0, (uint)dllBytes.Length, VirtualAllocFlags.COMMIT | VirtualAllocFlags.RESERVE, 0x40000);
        Marshal.Copy(dllBytes, 0, dllBaseAddress, dllBytes.Length);

        // 2. 获取 DLL 的导出函数地址
        IntPtr entryPointAddress = GetProcAddress(dllBaseAddress, entryPointName);

        if (entryPointAddress == IntPtr.Zero)
        {
            throw new Exception("Could not find entry point function: " + entryPointName);
        }

        // 3. 调用 DLL 的导出函数
        IntPtr result = Marshal.GetFunctionPointer(entryPointAddress);

        // 4. (可选) 释放内存
        // FreeLibrary(dllBaseAddress); // 如果 DLL 不再需要，释放内存

        return result;
    }

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr VirtualAlloc(
        IntPtr lpAddress,
        uint dwSize,
        VirtualAllocFlags flAllocationType,
        uint flProtect
    );

    [Flags]
    private enum VirtualAllocFlags : uint
    {
        RESERVE = 0x10000,
        COMMIT = 0x1000,
        EXECUTE = 0x10000000
    }
}
